function density(m,V){ if(V===0) return null; return m/V; }
function mass(rho,V){ return rho*V; }
function volume(m,rho){ if(rho===0) return null; return m/rho; }
function specificGravity(rho){ return rho/1000; } // 相对水(1000 kg/m³)
var EXPORTS={density:density, mass:mass, volume:volume, specificGravity:specificGravity};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DensityForgePure = EXPORTS; }
